solution:
def add_task(tasks, title, priority):
    task_id = len(tasks) + 1
    tasks.append({'id': task_id, 'title': title, 'priority': priority, 'done': False})
    return tasks

def complete_task(tasks, task_id):
    for task in tasks:
        if task['id'] == task_id:
            task['done'] = True
            return True
    return False

def get_pending(tasks):
    return sorted([t for t in tasks if not t['done']], key=lambda t: t['priority'])

def get_by_priority(tasks, priority):
    return [t for t in tasks if t['priority'] == priority]

def summary(tasks):
    done = sum(1 for t in tasks if t['done'])
    return {'total': len(tasks), 'done': done, 'pending': len(tasks) - done}
